30,"max":30,"atk":5,"def":1},{"id":"m6","key":"m_guard","name":"宝物庫の衛兵","x":64,"y":4,"hp":45,"max":45,"atk":6,"def":3},{"id":"m7","key":"m_wisp","name":"紅蓮のウィスプ","x":65,"y":25,"hp":30,"max":30,"atk":5,"def":1},{"id":"m8","key":"m_bat","name":"結晶コウモリ","x":70,"y":13,"hp":28,"max":28,"atk":5,"def":1},{"id":"guardian","key":"m_golem","name":"琥珀鍵の石守","x":50,"y":4,"hp":140,"max":140,"atk":9,"def":3,"dropKey":"amber","elite":true},{"id":"weaver","key":"m_spider","name":"紫鍵の織り手","x":51,"y":20,"hp":130,"max":130,"atk":8,"def":2,"dropKey":"violet","elite":true},{"id":"vesper","key":"boss_vesper","name":"結晶門の守護者ヴェスパー","x":81,"y":12,"hp":480,"max":480,"atk":16,"def":4,"boss":true}]}'::jsonb) on conflict(id) do update set data=excluded.data;
